:</span> <?= e($view['email']?:'—') ?></div><div><span class="font-bold text-slate-400">Subject:</span> <?= e($view['subject']?:'Website enquiry') ?></div></div><div class="mt-5 rounded-2xl bg-slate-50 p-5"><p class="whitespace-pre-line text-sm leading-7 text-slate-700"><?= e($view['message']) ?></p></div><div class="mt-5 grid grid-cols-2 gap-3"><?php if($view['phone']): ?><a href="tel:<?= e(phone_link($view['phone'])) ?>" class="flex items-center justify-center gap-2 rounded-xl bg-brand-700 px-4 py-3 font-extrabold text-white"><i data-lucide="phone" class="h-4 w-4"></i>Call</a><?php endif; ?><?php if($view['email']): ?><a href="mailto:<?= e($view['email']) ?>" class="flex items-center justify-center gap-2 rounded-xl bg-slate-800 px-4 py-3 font-extrabold text-white"><i data-lucide="mail" class="h-4 w-4"></i>Email</a><?php endif; ?></div><form method="post" class="mt-6 grid gap-4"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$view['id'] ?>"><label class="grid gap-2 text-sm font-bold">Status<select class="form-input" name="status"><?php foreach(['New','Read','Replied','Closed'] as $status): ?><option <?= $view['status']===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select></label><label class="grid gap-2 text-sm font-bold">Admin Notes<textarea class="form-input min-h-28" name="admin_notes"><?= e($view['admin_notes']) ?></textarea></label><button class="rounded-xl bg-brand-950 px-5 py-3 font-extrabold text-white">Update Message</button></form></aside><?php endif; ?></div>
